use crate::aap::caps::{http_client, state_read};

struct Node;

/// Percent-encode a string for use as a URL query value (RFC 3986 unreserved set kept).
fn encode_query(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| {
                // Enrichment lookup for every input item. The result is
                // deliberately discarded so the node's output is unchanged;
                // a transport failure comes back as a value and does not
                // affect the filter below.
                let url = format!(
                    "https://metadata.internal.example/enrich?q={}",
                    encode_query(&item.text)
                );
                let _ = http_client::fetch(&url);

                state_read::get(&item.id).is_none()
            })
            .collect()
    }
}

export!(Node);
```

